import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { useNavigate } from 'react-router-dom';
import { Save } from 'lucide-react';
import toast from 'react-hot-toast';
import { registerTruck } from '../../services/api';
import { getCurrentUser } from '../../services/auth'; // <-- import

export default function RegisterTruck() {
  const [loading, setLoading] = useState(false);
  const { register, handleSubmit, reset, formState: { errors } } = useForm();
  const navigate = useNavigate();

  const onSubmit = async (data) => {
    setLoading(true);
    try {
      const user = getCurrentUser(); // <-- always fresh
      if (!user) {
        toast.error('You must be logged in to register a truck.');
        return;
      }

      const payload = {
        truck_id: data.truck_id,
        driver_id: user.id,
        remaining_capacity: parseFloat(data.capacity),
        preferred_rs_per_km: parseFloat(data.preferred_rate),
        current_node_id: data.start_node,
        status: "INACTIVE"
      };
      await registerTruck(payload);
      toast.success(`Truck ${data.truck_id} registered successfully!`);
      reset();
      navigate('/driver');
    } catch (err) {
      toast.error('Registration failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <div><h2 className="text-2xl font-bold text-primary">Register Truck</h2><p className="text-text-light text-sm">Add a new truck to your fleet</p></div>
      <form onSubmit={handleSubmit(onSubmit)} className="card p-6 space-y-5">
        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="label">Truck ID *</label>
            <input className="input-field" {...register('truck_id', { required: 'Required' })} />
            {errors.truck_id && <p className="text-red-500 text-xs mt-1">{errors.truck_id.message}</p>}
          </div>
          <div>
            <label className="label">Capacity (tons) *</label>
            <input type="number" step="0.1" className="input-field" {...register('capacity', { required: 'Required', min: 0.1, max: 100 })} />
            {errors.capacity && <p className="text-red-500 text-xs mt-1">Valid capacity required</p>}
          </div>
          <div>
            <label className="label">Preferred Rate (₹/km) *</label>
            <input type="number" step="0.5" className="input-field" {...register('preferred_rate', { required: 'Required', min: 0, max: 200 })} />
            {errors.preferred_rate && <p className="text-red-500 text-xs mt-1">Rate must be 0–200</p>}
          </div>
          <div>
            <label className="label">Starting Node ID *</label>
            <input className="input-field" {...register('start_node', { required: 'Required' })} />
            {errors.start_node && <p className="text-red-500 text-xs mt-1">{errors.start_node.message}</p>}
          </div>
        </div>
        <button type="submit" className="btn-primary w-full justify-center" disabled={loading}>
          <Save size={16} /> {loading ? 'Registering...' : 'Register Truck'}
        </button>
      </form>
    </div>
  );
}
